4	import com.example.starter.survey.domain.IdempotentRecord;
5	import com.example.starter.survey.web.ConflictException;
6	import com.example.starter.survey.web.dto.ApiResult;
7	import com.fasterxml.jackson.databind.ObjectMapper;
8	import org.springframework.stereotype.Component;
9	import org.springframework.transaction.annotation.Transactional;
10	import org.springframework.transaction.interceptor.TransactionAspectSupport;
11	
12	import java.time.Instant;
13	
14	/**
15	 * 幂等执行器：所有写操作在同一数据库事务内完成“指纹校验 → 占键 → 业务 → 回填结果”。
16	 * <ul>
17	 *   <li>同键同参：重放首次结果（{@link ApiResult#replayed} 为 true）；</li>
18	 *   <li>同键异参：409，不执行业务、不产生新证书；</li>
19	 *   <li>业务异常：整体回滚（含占键记录），重放将重新得到同样的业务结果；</li>
20	 *   <li>并发同键：唯一索引保证只有一个首插成功，落败方读取已提交结果重放。</li>
21	 * </ul>
22	 */
23	@Component
24	public class IdempotentExecutor {
25	
26	    private final IdempotencyRepository repository;
27	    private final ObjectMapper objectMapper;
28	    private final TimeProvider timeProvider;
29	
30	    public IdempotentExecutor(IdempotencyRepository repository,
31	                              ObjectMapper objectMapper,
32	                              TimeProvider timeProvider) {
33	        this.repository = repository;
34	        this.objectMapper = objectMapper;
35	        this.timeProvider = timeProvider;
36	    }
37	
38	    /**
39	     * 在事务内以幂等方式执行业务动作。
40	     *
41	     * @param requestId   幂等键
42	     * @param fingerprint 业务指纹（requestId + 操作类型 + 全部业务字段）
43	     * @param resultType  成功结果类型，用于重放时反序列化首次响应
44	     * @param action       首次受理时执行的业务动作
45	     */
46	    @Transactional
47	    public <T> ApiResult<T> run(String requestId, String fingerprint,
48	                                Class<T> resultType, SupplierWithExcept<T> action) {
49	        // 最多两次：极端并发下对方事务回滚、占键消失后可重新抢占。
50	        for (int attempt = 0; attempt < 2; attempt++) {
51	            var existing = repository.find(requestId);
52	            if (existing.isPresent()) {
53	                return replayOrConflict(requestId, fingerprint, existing.get(), resultType);
54	            }
55	            if (!repository.reserve(requestId, fingerprint, timeProvider.now())) {
56	                continue;
57	            }
58	            T result;
59	            try {
60	                result = action.get();
61	            } catch (RuntimeException ex) {
62	                // 抛出后事务回滚，占键与业务写入一并撤销。
63	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
64	                throw ex;
65	            }
66	            String body;
67	            try {
68	                body = objectMapper.writeValueAsString(result);
69	            } catch (Exception e) {
70	                TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
71	                throw new IllegalStateException("响应序列化失败", e);
72	            }
73	            repository.complete(requestId, 200, body);
74	            return ApiResult.first(result, requestId);
75	        }
76	        throw new ConflictException("IDEMPOTENCY_RACE",
77	                "幂等键并发处理异常，请稍后按相同参数重放: " + requestId);
78	    }
79	
80	    private <T> ApiResult<T> replayOrConflict(String requestId, String fingerprint,
81	                                              IdempotentRecord record, Class<T> resultType) {
82	        if (!record.fingerprint().equals(fingerprint)) {
83	            throw new ConflictException("IDEMPOTENCY_FINGERPRINT_MISMATCH",
84	                    "requestId 已用于不同的业务请求: " + requestId);
85	        }
86	        if (record.httpStatus() == IdempotencyRepository.STATUS_PENDING) {
87	            // 另一事务仍在处理：直接按冲突返回，提示稍后用相同参数重放，不重复执行业务。
88	            throw new ConflictException("IDEMPOTENCY_IN_FLIGHT",
89	                    "相同 requestId 的请求正在处理中: " + requestId);
90	        }
91	        try {
92	            T data = objectMapper.readValue(record.responseBody(), resultType);
93	            return ApiResult.replay(data, requestId);
94	        } catch (Exception e) {
95	            throw new IllegalStateException("历史响应反序列化失败", e);
96	        }
97	    }
98	
99	    /** 允许动作抛出受检异常包装为非受检的函数式接口。 */
100	    @FunctionalInterface
101	    public interface SupplierWithExcept<T> {
102	        T get();
103	    }
104	
105	    /** 当前时间便捷方法（供服务构造指纹时间戳场景统一使用）。 */
106	    public Instant now() {
107	        return timeProvider.now();
108	    }
109	}
