48	    /** 进行中检验唯一索引冲突时抛出，由服务层转为 409。 */
49	    public static class ActiveSurveyConflict extends RuntimeException {
50	        public ActiveSurveyConflict(Throwable cause) {
51	            super(cause);
52	        }
53	    }
