55	    /** 申请受理：插入进行中检验。 */
56	    public Survey insert(String requestId, long shipId, SurveyType type,
57	                         LocalDate anchor, LocalDate windowStart, LocalDate windowEnd,
58	                         String fingerprint, Instant now) {
59	        try {
60	            jdbc.update("""
