109	    public void updateExtensionUntil(long surveyId, LocalDate extensionUntil) {
110	        jdbc.update("UPDATE survey SET extension_until = ? WHERE id = ?",
111	                Date.valueOf(extensionUntil), surveyId);
112	    }
