114	    /** 发证：终态 CERTIFIED，释放 active_flag（唯一索引槽位）。 */
115	    public void markCertified(long surveyId, Instant certifiedAt) {
116	        int updated = jdbc.update("""
117	                        UPDATE survey SET status = 'CERTIFIED', certified_at = ?, active_flag = NULL
118	                        WHERE id = ?
119	                        """, Timestamp.from(certifiedAt), surveyId);
120	        if (updated != 1) {
121	            throw new IllegalStateException("发证更新行数异常: " + updated);
122	        }
123	    }
