```java
@Service
public class FlagRuleService {
    // upsert
    public ApiResult<FlagRuleVersionResponse> upsert(UpsertFlagRuleRequest request) {
        // validate mappings: distinct flagItemCode and classItemCode? flag item unique per rule (unique index). class item could repeat? mapping flag->class; multiple flag items could map to same class item? Possibly, but keep simple: require distinct flagItemCode (else 400) — unique index would throw otherwise.
        Map<String,Object> fields = new LinkedHashMap<>();
        fields.put("flagCode", request.flagCode());
        fields.put("expectedVersion", request.expectedVersion());
        fields.put("maxEvidenceAgeDays", request.maxEvidenceAgeDays());
        fields.put("mappings", mappingFingerprints(request.mappings()));
