        assertEquals("REPORT_CONTENT_CONFLICT", conflictItems.get("code").asText());
        assertEquals(1, jdbc.queryForObject(
                "SELECT COUNT(*) FROM flag_inspection_report WHERE report_no='FR-2001'",
